void rvk_glGetTexImage(::rvk::protocol::Transport& rvk_t, GLenum target, GLint level, GLenum format, GLenum type, void* pixels, std::size_t pixels_bytes, bool pixels_is_offset) {
    RVK_PROF_SCOPE("gl:glGetTexImage");
    ::av::WireWriter rvk_b;
    rvk_b.write_varint(static_cast<std::uint64_t>(target));
    rvk_b.write_varint(static_cast<std::uint64_t>(level));
    rvk_b.write_varint(static_cast<std::uint64_t>(format));
    rvk_b.write_varint(static_cast<std::uint64_t>(type));
    const std::size_t pixels_want = static_cast<std::size_t>(pixels_bytes);
    ::rvk::client::BlobArena::Lease pixels_lease{};
    bool pixels_via_blob = false;
    if (!pixels_is_offset && pixels != nullptr &&
        pixels_want >= ::av::glproto::kPixelBlobFloor) {
        auto& rvk_blobs = ::rvk::client::BlobArena::for_transport(rvk_t);
        if (rvk_blobs.ready()) {
            pixels_lease = rvk_blobs.take(pixels_want);
            pixels_via_blob = pixels_lease.ok();
            if (pixels_via_blob) std::memset(pixels_lease.data, 0, pixels_want);
        }
    }
    rvk_b.write_pod<std::uint8_t>(
        pixels_is_offset ? 2 : (pixels_via_blob ? 3 : (pixels != nullptr ? 1 : 0)));
    if (pixels_is_offset) {
        rvk_b.write_varint(static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(pixels)));
    } else if (pixels_via_blob) {
        rvk_b.write_varint(static_cast<std::uint64_t>(pixels_want));
        rvk_b.write_varint(static_cast<std::uint64_t>(pixels_lease.offset));
    } else if (pixels != nullptr) {
        rvk_b.write_varint(static_cast<std::uint64_t>(pixels_want));
    }
    if (rvk_b.status() != ::av::Status::ok) {
        ::rvk::client::payload_dropped("gl", "glGetTexImage",
                                       rvk_b.offset());
        return;
    }
    ::av::WireWriter rvk_reply;
    const bool rvk_sent = rvk_t.send_sync(kCmd_glGetTexImage, rvk_b.bytes(), &rvk_reply) ==
        ::rvk::protocol::TransportResult::Ok;
    if (!rvk_sent) {
        return;
    }
    ::av::WireReader rvk_r{rvk_reply.bytes()};
    if (pixels_via_blob) {
        std::memcpy(pixels, pixels_lease.data, pixels_want);
        ::rvk::client::BlobArena::for_transport(rvk_t)
            .give_back(pixels_lease);
    }
    if (pixels != nullptr && !pixels_is_offset && !pixels_via_blob) {
        std::uint64_t rvk_bytes = 0;
        if (!rvk_r.read_varint(rvk_bytes)) return;
        if (rvk_bytes > static_cast<std::uint64_t>(pixels_want)) return;
        if (rvk_bytes != 0 &&
            !rvk_r.read(pixels, static_cast<std::size_t>(rvk_bytes))) return;
    }
}

